package com.emp.ems;
import com.fasterxml.jackson.databind.ObjectMapper;import io.jsonwebtoken.*;import io.jsonwebtoken.security.Keys;import jakarta.servlet.*;import jakarta.servlet.http.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.context.annotation.*;import org.springframework.http.HttpMethod;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.config.http.SessionCreationPolicy;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.security.web.SecurityFilterChain;import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;import org.springframework.stereotype.Component;import org.springframework.web.cors.*;import org.springframework.web.filter.OncePerRequestFilter;import javax.crypto.SecretKey;import java.io.IOException;import java.time.Instant;import java.util.*;
@Configuration @EnableMethodSecurity
public class SecurityConfig{
 @Bean PasswordEncoder encoder(){return new BCryptPasswordEncoder(12);}
 @Bean SecurityFilterChain security(HttpSecurity http,JwtFilter jwt,CorsConfigurationSource cors)throws Exception{return http.cors(c->c.configurationSource(cors)).csrf(c->c.disable()).sessionManagement(c->c.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers(HttpMethod.OPTIONS,"/**").permitAll().requestMatchers("/api/v1/auth/login","/actuator/health").permitAll().requestMatchers("/api/v1/admin/**","/actuator/prometheus").hasRole("ADMIN").requestMatchers("/api/v1/employee/**").hasAnyRole("EMPLOYEE","ADMIN").requestMatchers("/api/v1/auth/logout","/api/v1/auth/me").authenticated().anyRequest().denyAll()).exceptionHandling(e->e.authenticationEntryPoint((q,r,x)->json(r,401,"Please sign in to continue.")).accessDeniedHandler((q,r,x)->json(r,403,"You do not have access to this resource."))).headers(h->h.contentSecurityPolicy(c->c.policyDirectives("default-src 'none'; frame-ancestors 'none'"))).addFilterBefore(jwt,UsernamePasswordAuthenticationFilter.class).build();}
 static void json(HttpServletResponse response,int status,String message)throws IOException{response.setStatus(status);response.setContentType("application/json");new ObjectMapper().writeValue(response.getWriter(),Map.of("message",message));}
 @Bean CorsConfigurationSource cors(@Value("${ems.cors-origins}")String origins){CorsConfiguration c=new CorsConfiguration();c.setAllowedOrigins(Arrays.stream(origins.split(",")).map(String::trim).toList());c.setAllowedMethods(List.of("GET","POST","PATCH","OPTIONS"));c.setAllowedHeaders(List.of("Authorization","Content-Type"));c.setMaxAge(3600L);c.setAllowCredentials(false);UrlBasedCorsConfigurationSource source=new UrlBasedCorsConfigurationSource();source.registerCorsConfiguration("/api/**",c);return source;}
}
@Component class JwtService{private final SecretKey key;private final long minutes;JwtService(@Value("${ems.jwt-secret}")String secret,@Value("${ems.jwt-expiration-minutes}")long minutes){byte[] bytes;try{bytes=Base64.getDecoder().decode(secret);}catch(IllegalArgumentException e){throw new IllegalStateException("JWT_SECRET must be base64-encoded");}if(bytes.length<32||minutes<1||minutes>1440)throw new IllegalStateException("JWT_SECRET needs 32+ random bytes; expiry must be 1–1440 minutes");this.key=Keys.hmacShaKeyFor(bytes);this.minutes=minutes;}String issue(Employee e){Instant now=Instant.now();return Jwts.builder().subject(e.id.toString()).issuer("forma-ems").id(UUID.randomUUID().toString()).claim("version",e.authVersion).issuedAt(Date.from(now)).expiration(Date.from(now.plusSeconds(minutes*60))).signWith(key).compact();}Claims parse(String token){return Jwts.parser().verifyWith(key).requireIssuer("forma-ems").build().parseSignedClaims(token).getPayload();}}
record CurrentUser(UUID id,String role){}
@Component class JwtFilter extends OncePerRequestFilter{private final JwtService jwt;private final EmployeeRepository employees;JwtFilter(JwtService jwt,EmployeeRepository employees){this.jwt=jwt;this.employees=employees;}@Override protected void doFilterInternal(HttpServletRequest request,HttpServletResponse response,FilterChain chain)throws ServletException,IOException{String header=request.getHeader("Authorization");if(header!=null&&header.startsWith("Bearer ")){try{Claims claims=jwt.parse(header.substring(7));Employee e=employees.findById(UUID.fromString(claims.getSubject())).orElseThrow();Object version=claims.get("version");if(!(version instanceof Number)||e.authVersion!=((Number)version).longValue())throw new IllegalArgumentException("Revoked token");SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(new CurrentUser(e.id,e.role),null,List.of(new SimpleGrantedAuthority("ROLE_"+e.role))));}catch(JwtException|IllegalArgumentException|NoSuchElementException ex){SecurityContextHolder.clearContext();SecurityConfig.json(response,401,"Your session has expired. Please sign in again.");return;}}chain.doFilter(request,response);}}
